!function(e){function t(t){for(var a,i,m=t[0],o=t[1],d=t[2],s=0,g=[];s<m.length;s++)i=m[s],Object.prototype.hasOwnProperty.call(p,i)&&p[i]&&g.push(p[i][0]),p[i]=0;for(a in o)Object.prototype.hasOwnProperty.call(o,a)&&(e[a]=o[a]);for(c&&c(t);g.length;)g.shift()();return n.push.apply(n,d||[]),r()}function r(){for(var e,t=0;t<n.length;t++){for(var r,i=n[t],m=!0,o=1;o<i.length;o++)r=i[o],0!==p[r]&&(m=!1);m&&(n.splice(t--,1),e=a(a.s=i[0]))}return e}function a(t){if(i[t])return i[t].exports;var r=i[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var i={},p={12:0},n=[];a.m=e,a.c=i,a.d=function(e,t,r){a.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,t){if(1&t&&(e=a(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)a.d(r,i,function(t){return e[t]}.bind(null,i));return r},a.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(t,"a",t),t},a.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},a.p="";var m=window.webpackJsonp=window.webpackJsonp||[],o=m.push.bind(m);m.push=t,m=m.slice();for(var d=0;d<m.length;d++)t(m[d]);var c=o;n.push([96,0]),r()}({96:function(e,t,r){"use strict";r.r(t);var a=r(0);Object(a.a)("de","army",r(97),r(1))},97:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"半履带装甲车辆","link":"de_army#de_army_avhtv"}],"model":"251/17型半履带装甲防空炮车","description":"<p>东线战事开始后，德军装甲部队由于缺乏防空保护，在苏军飞机的空袭下受到了不少损失，1942年，在东线作战的德军大德意志装甲掷弹兵师就将自身装备的Flak 38型20mm牵引式轻型防空炮安装在251/1 C型和D型运兵车上，改装为半履带装甲自行防空炮车，以对付低空攻击德军坦克与运输车的苏军飞机，并将这种临时改装的防空炮车命名为陆军专用型251/17自行防空炮车。</p><p>而同在1942年，德国空军也将Flak 38型20mm防空炮安装在251 C车体上，定名为251/7空军专用型自行防空炮车，只是这种空军专用型防空炮车对车厢作了较大改动，对空作战的效果较好，但由于造价较高，实际生产数量并不多。</p><p>1943年，德军将Flak 38型20mm防空炮安装在3吨的半履带牵引车上，并采用了与251车体发动机舱的相同结构，成为一种新型车体的251/17自行防空炮车。</p><p>1944年，德军在251 D型车体上将防空炮改为安装20mm机关炮，使之成为对空和对地两用的火力装备，名为251/17半履带装甲自行机关炮车。</p><p>251/17型自行防空炮车自装备德军后，已成为德军装甲部队重要的防空装备，在东、西线战场上一直坚持战斗到二战结束。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_avhtv25117_11.jpg","description":"<h6>陆军专用型251/17自行防空炮车</h6><p>该炮车的车厢中部安装有一门Flak 38型20mm轻型防空炮，最大备弹量600发，由于车厢宽度狭窄，所以使防空炮的左右射界受到很大限制，影响了战斗力的发挥。</p><p>该型炮车核载乘员6人，除1名驾驶员和1名机电员外，其余为炮手。</p><p>陆军专用型251/17自行防空炮车由德国“大德意志”装甲掷弹兵师改装，主要作用是防空作战，掩护东线战场上的德军装甲部队与运输部队。</p>","caption":""},{"image":"{{text}}炮车四视图（线图）{{image}}imgs/de/army/de_army_avhtv25117_12.jpg","description":"<h6>空军专用型251/17半履带自行防空炮车</h6><p>该炮车用251/1 C型改装，该车对车厢进行了改造，车厢中部两侧的装甲板在对空作战时可以放平，使防空炮在射击时可作360°转动，让防空炮的战斗力得到充分发挥。</p><p>该型炮车也是安装一门Flak 38型20mm轻型防空炮，备弹量600发。</p><p>车上核载乘员7人，包括1名驾驶员、1名机电员和5名炮手。</p><p>空军专用型251/17半履带自行防空炮车产量非常少，仅仅装备了德军“赫尔曼·格林”伞兵装甲师。</p>","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_13.jpg","description":"<h6>Sd Kfz 251/17新型车体3吨半履带自行防空炮车</h6><p>该型炮车于1944年3月开始改装，将20mm防空炮安装在3吨的半履带牵引车后部平板上，防空炮两侧安装有网状可收放的护板，对空作战时，可将护板放平，以便防空炮进行360°转动射击。由于炮车的车体与底盘与Sd Kfz 251 Ausf D完全相同，量产后车体的前部结构全部按照251 D型车生产，因此称之为新型车体的251/17半履带自行防空炮车。</p><p>该炮车从1944年3月至1945年2月共生产了604辆，期后亦有产出，但数量不详。由于该炮车对炮手基本没有装甲防护，因此战场生存率很低。</p>","caption":""},{"image":"{{text}}炮车四视图{{image}}imgs/de/army/de_army_avhtv25117_14.jpg","description":"<h6>Sd Kfz 251/17 Ausf D型半履带装甲自行机关炮车</h6><p>战争后期，20mm防空炮已难以对付苏军与盟军的飞机，且为了加强德军地面战斗的火力，就在251 D型车体上改装20mm机关炮，既作防空又作地面攻击用，并将此车称为251/17半履带自行机关炮车。该炮车在车厢前部或中部安装1门20mm机关炮（该炮火力比防空炮要弱），环绕炮身有防护装甲，车厢后部安装一挺MG42型机枪。</p><p>该炮车核载乘员5人：1名驾驶员、1名机电员、1名炮手和2名弹药手，其中弹药手兼后置机枪的射手。该车数量不多，至1944年底德军只装备了15辆。</p>","caption":""}],"part2title":"战场上的251/17型半履带装甲防空炮车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_avhtv25117_21.jpg","description":"1943～1944年冬天，东线战场，隶属德国“大德意志”装甲掷弹兵师的一辆用251/1 C型改装的陆军专用型251/17半履带装甲自行防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_22.jpg","description":"1944年秋天，德国东普鲁士地区，隶属德国“赫尔曼·戈林”伞兵装甲师防空团的一辆用251/1 C型改装的空军专用型251/17半履带装甲自行防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_23.jpg","description":"1945年春天，德国地区，隶属德军“明赫贝格”装甲师的一辆251/17新型车体3吨半履带自行防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_24.jpg","description":"1944年7月，法国诺曼底地区，隶属德国武装党卫军第12“希特勒青年团”装甲师的一辆Sd Kfz 251/17 Ausf D型半履带自行机关炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_25.jpg","description":"1943年春天，东线苏联战场，正在向前线进发的德国“大德意志”装甲掷弹兵师的一辆用251/1 C型改装的陆军专用型251/17半履带装甲自行防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_26.jpg","description":"1943年春天，东线苏联战场，正在向前线进发的德国“大德意志”装甲掷弹兵师的一辆用251/1 C型改装的陆军专用型251/17半履带装甲自行防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_27.jpg","description":"1942年，被德国空军运到东线苏联战场作实战测试的空军专用型251/17半履带防空炮车。该型炮车生产数量并不多，只装备了德军的“赫尔曼·戈林”伞兵装甲师防空团。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_28.jpg","description":"在东线苏联战场上作战的一辆德军空军专用型251/17半履带防空炮车。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_29.jpg","description":"1944年秋天，西线战场，一辆正在作火力支援的德军3吨半履带251/17型防空炮车。该型炮车装甲防护薄弱，在盟军飞机袭击中，不但起不到防空作用，还常常被击毁，战场上生存能力严重不足。注意该车车厢的网格状侧板可放下，在对空战斗时使防空炮能360°转动射击。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_30.jpg","description":"1944年，西线战场阿登反击战，一辆被盟军地面炮火摧毁的德军半履带251/17 D型防空机关炮车。该型炮车在1944年才装备德军，尽管数量不多，但都曾在东线与西线战场上作战；改装机关炮后，作地面火力支援比作防空作战还要多。","caption":""},{"image":"imgs/de/army/de_army_avhtv25117_31.jpg","description":"这是一辆与251/17空防战车同时装备的空军专用的防空指挥车，它在251/17防空炮车上拆除了20mm防空炮，装上了一台大功率电台，并在车厢四周装上了框形天线，该型车上有空军防空小队的指挥军官，可同时指挥四辆251/17防空炮车作战。","caption":""}]}')}});